        clipBusy=true;favorite.disabled=true;favorite.textContent='收藏中…';for(const id of ['ai-clip-title','ai-clip-note','ai-crop-pen','ai-crop-circle','ai-crop-reset','ai-crop-undo'])layer.querySelector('#'+id).disabled=true;
